import type { Page } from "playwright";
import { readFile } from "node:fs/promises";
import { createHmac } from "node:crypto";
import path from "node:path";
import assert from "node:assert/strict";

/** Read only the email generated by this browser request, never an older OTP. */
export async function emailCode(
  page: Page,
  click: () => Promise<unknown>,
  admin = false,
) {
  const endpoint = admin ? "/v1/admin/auth/challenge" : "/v1/auth/challenge";
  for (let attempt = 0; attempt < 4; attempt++) {
    const [response] = await Promise.all([
      page.waitForResponse(
        (r) =>
          new URL(r.url()).pathname === endpoint &&
          r.request().method() === "POST",
      ),
      click(),
    ]);
    const body = await response.json();
    if (response.status() === 429 && attempt < 3) {
      console.log("Waiting for the normal email challenge rate window");
      await new Promise((r) => setTimeout(r, 31000));
      continue;
    }
    assert.equal(response.status(), 200, JSON.stringify(body));
    const file = path.resolve(
      "../copypaste-platform/.data/mailbox",
      body.challenge_id + ".json",
    );
    const mail = JSON.parse(await readFile(file, "utf8"));
    assert.equal(mail.to, response.request().postDataJSON().email);
    return mail.text.match(/code is (\d{6})/)[1] as string;
  }
  throw new Error("Email challenge rate window did not reopen");
}
export function authenticatorCode(secret: string) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  const bits = [...secret]
    .map((c) => alphabet.indexOf(c).toString(2).padStart(5, "0"))
    .join("");
  const bytes = Buffer.from(bits.match(/.{8}/g)!.map((v) => parseInt(v, 2))),
    counter = Buffer.alloc(8);
  counter.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
  const digest = createHmac("sha1", bytes).update(counter).digest(),
    offset = digest[19] & 15;
  return ((digest.readUInt32BE(offset) & 0x7fffffff) % 1000000)
    .toString()
    .padStart(6, "0");
}
/** Respect the real one-use TOTP counter when journeys share the QA operator. */
export async function verifyAdmin(page: Page, secret: string) {
  for (let attempt = 0; attempt < 2; attempt++) {
    await page.locator('input[name="totp"]').fill(authenticatorCode(secret));
    const [r] = await Promise.all([
      page.waitForResponse(
        (r) =>
          new URL(r.url()).pathname === "/v1/admin/auth/verify" &&
          r.request().method() === "POST",
      ),
      page
        .getByRole("button", { name: "Verify & open dashboard", exact: true })
        .click(),
    ]);
    if (r.ok()) return;
    if (attempt || r.status() !== 401)
      throw new Error("Administrator sign-in failed: " + r.status());
    await new Promise((resolve) =>
      setTimeout(resolve, 30500 - (Date.now() % 30000)),
    );
  }
}
